UPDATE b_daily_train_ticket
SET remaining = remaining - #{count}
WHERE ride_date = #{rideDate}
  AND train_code = #{trainCode}
  AND from_station = #{fromStation}
  AND to_station = #{toStation}
  AND seat_type = #{seatType}
  AND remaining >= #{count}

UPDATE b_daily_train_ticket
SET remaining = remaining + #{count}
WHERE ride_date = #{rideDate}
  AND train_code = #{trainCode}
  AND from_station = #{fromStation}
  AND to_station = #{toStation}
  AND seat_type = #{seatType}
